arguments.command:
cd /app; for f in seeds/*; do echo $f; python3 - $f <<'E'
import sys
b=open(sys.argv[1],'rb').read()
try: b.decode('utf-8');print('utf8 ok', b[:3]==b'\xef\xbb\xbf', b'\r\n' in b)
except Exception as e: print('not utf8',e)
try: b.decode('cp1252');print('cp1252 ok')
except Exception as e: print(e)
E
done; cut -d, -f8 seeds/specimens.csv|sort|uniq -c; grep -c . seeds/*; sqlite3 -version; python3 -c "
import sqlite3;c=sqlite3.connect('releases/1.6.0/herbarium.sqlite')
print(c.execute('select count(*),min(elevation_ft),max(elevation_ft) from specimen').fetchall());print(c.execute('select distinct basis from specimen').fetchall())
print(c.execute('select version,name from schema_migrations').fetchall())"

