arguments.command:
cd /app; python3 -c "
import tomllib;print(tomllib.load(open('stratum.toml','rb'))['seed'][3]['map'])"
python3 - <<'E'
import sqlite3,subprocess,shutil
shutil.copy('releases/1.6.0/herbarium.sqlite','/tmp/u.sqlite')
print(subprocess.run(['python3','tools/stratum.py','upgrade','/tmp/u.sqlite'],capture_output=True,text=True).stdout[-200:])
a=sqlite3.connect('build/herbarium.sqlite');b=sqlite3.connect('/tmp/u.sqlite')
for q in ["select type,name,tbl_name from sqlite_master where name not like 'sqlite_%' order by 1,2","select * from specimen order by 1","select * from taxon order by 1","select * from site order by 1","select * from collector order by 1"]:
    x=a.execute(q).fetchall();y=b.execute(q).fetchall();print(q[:30],x==y,len(x),len(y))
    if x!=y:
        for r in [r for r in x if r not in y][:3]:print(' fresh',r)
        for r in [r for r in y if r not in x][:3]:print(' upg',r)
for d in (a,b):print(sorted((r[1],r[2]) for t in ['specimen','taxon'] for r in d.execute(f"pragma table_xinfo({t})")))
E

